import test from 'node:test';import assert from 'node:assert/strict';
import {createKickSidechain,kickAtStep,sidechainTiming} from './sidechain.js';
function context(){const nodes=[];return {currentTime:1,createGain(){const calls=[],gain={value:1,cancelScheduledValues:t=>calls.push(['cancel',t]),setValueAtTime:(v,t)=>calls.push(['set',v,t]),setTargetAtTime:(v,t,k)=>calls.push(['target',v,t,k])};const node={gain,calls};nodes.push(node);return node},nodes}}
test('kick detection respects pattern length, mute and solo',()=>{const p={length:4,steps:[Array.from({length:4},(_,i)=>({on:i===0,velocity:1,probability:1}))]};const d={voices:Array.from({length:11},()=>({mute:false,solo:false})),bank:{patterns:[p]},selectedPattern:0};assert.equal(kickAtStep(d,0),1);assert.equal(kickAtStep(d,4),1);assert.equal(kickAtStep(d,3),0);d.voices[0].mute=true;assert.equal(kickAtStep(d,0),0);d.voices[0].mute=false;d.voices[1].solo=true;assert.equal(kickAtStep(d,0),0);d.voices[0].solo=true;assert.equal(kickAtStep(d,0),1)});
test('timings and envelope depth are bounded',()=>{const p=sidechainTiming({amount:1,attack:1,hold:1,release:1});assert.ok(p.attack>.06);assert.ok(p.release>1);assert.ok(p.depth<1)});
test('only enabled strips duck and scenes restore settings',()=>{const ctx=context(),sc=createKickSidechain();sc.connect(ctx,'drums');sc.connect(ctx,'mono');sc.connect(ctx,'poly');sc.setEnabled('mono',true);sc.trigger(1.1,1);assert.equal(ctx.nodes[0].calls.length,0);assert.equal(ctx.nodes[2].calls.length,0);assert.ok(ctx.nodes[1].calls.some(c=>c[0]==='target'&&c[1]<1));sc.setEnabled('mono',false);assert.ok(ctx.nodes[1].calls.some(c=>c[0]==='target'&&c[1]===1));sc.restore({params:{amount:.35,release:.5},enabled:{poly:true}});assert.equal(sc.params.amount,.35);sc.trigger(1.3);assert.ok(ctx.nodes[2].calls.some(c=>c[0]==='target'&&c[1]<1));sc.reset()});
